#!/usr/bin/env Rscript
suppressPackageStartupMessages({library(ggplot2);library(dplyr);library(tidyr)})
repo<-normalizePath(Sys.getenv('WS40_REPO',unset='.'));inp<-file.path(repo,'results/reproduced/collectri');out<-file.path(repo,'results/reproduced/figures/collectri');dir.create(out,recursive=TRUE,showWarnings=FALSE)
means<-read.csv(file.path(inp,'Ensembl_no_batch_condition_means.csv'));fs<-read.csv(file.path(inp,'Ensembl_no_batch_global_F.csv'));top<-head(fs$source[order(-fs$F_statistic)],30);d<-means[means$source%in%top,];d$source<-factor(d$source,levels=rev(top));d$treatment<-factor(d$treatment,levels=c('Normoxia','4hA','24hA','2hR','24hR'));g<-ggplot(d,aes(treatment,source,fill=score))+geom_tile()+scale_fill_gradient2(low='#2166AC',mid='white',high='#B2182B',midpoint=0)+labs(x=NULL,y=NULL,fill='TF activity',title='Top 30 treatment-responsive transcription factors')+theme_minimal(base_size=9)+theme(axis.text.x=element_text(angle=45,hjust=1));ggsave(file.path(out,'TF_top30_heatmap.png'),g,width=7,height=9,dpi=600);ggsave(file.path(out,'TF_top30_heatmap.pdf'),g,width=7,height=9);focus<-c('HSF1','HSF2','ERF','ATF6','ATF4','CREB1');p<-means[means$source%in%focus,];p$treatment<-factor(p$treatment,levels=c('Normoxia','4hA','24hA','2hR','24hR'));g2<-ggplot(p,aes(treatment,score,group=source,color=source))+geom_hline(yintercept=0,color='grey70')+geom_line()+geom_point(size=2)+labs(x=NULL,y='Mean normalized activity',color='TF')+theme_classic(base_size=10)+theme(axis.text.x=element_text(angle=45,hjust=1));ggsave(file.path(out,'TF_focus_profiles.png'),g2,width=6,height=4,dpi=600);ggsave(file.path(out,'TF_focus_profiles.pdf'),g2,width=6,height=4)
